#include <stdio.h>
#include <string.h>
int main() {
    char s1[100005], s2[100005];
    if (scanf("%s %s", s1, s2) == 2) {
        int n1 = strlen(s1), n2 = strlen(s2);
        if (n1 > n2) { puts("false"); return 0; }
        int c1[26] = {0}, c2[26] = {0};
        for (int i = 0; i < n1; i++) { c1[s1[i] - 'a']++; c2[s2[i] - 'a']++; }
        if (memcmp(c1, c2, sizeof(c1)) == 0) { puts("true"); return 0; }
        for (int i = n1; i < n2; i++) {
            c2[s2[i] - 'a']++;
            c2[s2[i - n1] - 'a']--;
            if (memcmp(c1, c2, sizeof(c1)) == 0) { puts("true"); return 0; }
        }
        puts("false");
    }
    return 0;
}

