import java.util.Scanner;
import java.util.Arrays;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNext()) {
            String s1 = sc.next(), s2 = sc.next();
            int n1 = s1.length(), n2 = s2.length();
            if (n1 > n2) { System.out.println("false"); return; }
            int[] c1 = new int[26], c2 = new int[26];
            for (int i = 0; i < n1; i++) { c1[s1.charAt(i) - 'a']++; c2[s2.charAt(i) - 'a']++; }
            if (Arrays.equals(c1, c2)) { System.out.println("true"); return; }
            for (int i = n1; i < n2; i++) {
                c2[s2.charAt(i) - 'a']++; c2[s2.charAt(i - n1) - 'a']--;
                if (Arrays.equals(c1, c2)) { System.out.println("true"); return; }
            }
            System.out.println("false");
        }
    }
}

