const fs = require("fs");
function main() {
    const toks = fs.readFileSync(0, "utf-8").trim().split(/\s+/);
    if (toks.length >= 2) {
        const s1 = toks[0], s2 = toks[1];
        const n1 = s1.length, n2 = s2.length;
        if (n1 > n2) { console.log("false"); return; }
        const c1 = new Array(26).fill(0), c2 = new Array(26).fill(0);
        for (let i = 0; i < n1; i++) {
            c1[s1.charCodeAt(i) - 97]++;
            c2[s2.charCodeAt(i) - 97]++;
        }
        const eq = (a, b) => a.every((v, i) => v === b[i]);
        if (eq(c1, c2)) { console.log("true"); return; }
        for (let i = n1; i < n2; i++) {
            c2[s2.charCodeAt(i) - 97]++;
            c2[s2.charCodeAt(i - n1) - 97]--;
            if (eq(c1, c2)) { console.log("true"); return; }
        }
        console.log("false");
    }
}
main();

